//! Original native userSend allocation and private result; never received or
//! UDMR permission. Budget admission precedes ID/WRITE arm; no automatic retry.
use super::*;
use super::super::{im_inbox::ImSendPermit,rpc_im_send::{ImSendRpcRequest,OwnedImSendReply}};
impl ArcRpcSession{
    pub(in super::super) fn prepare_im_send(&mut self,binding:Arc<super::super::im_delivery::ImBinding>,permit:Arc<ImSendPermit>,deadline:std::time::Instant)->Result<(i32,RpcBytes),CodecError>{let deadline=deadline.min(permit.deadline());if !self.native_receiver_scope()||!binding.matches(&self.owner,&self.connection)||!permit.matches(&self.owner,&self.connection)||!Arc::ptr_eq(&binding,permit.binding())||std::time::Instant::now()>=deadline{return Err(CodecError::InvalidField);}if self.pending.len()>=MAX_MAP_ENTRIES||self.im_reply_count()>=MAX_MAP_ENTRIES{return Err(CodecError::TooLarge);}let auth=self.authentication.as_ref().ok_or(CodecError::InvalidField)?;if !binding.authenticates(&auth.user_id,&auth.selected_session_id)||permit.token_for(&self.owner,&self.connection)!=Some(auth.token.as_slice()){return Err(CodecError::InvalidField);}let id=self.next_id.ok_or(CodecError::InvalidCallId)?;let bytes=encode_request(id,&[RpcProperty{key:b"id",value:b"#Group"},RpcProperty{key:b"token",value:&auth.token}],super::super::im_send_data::USER_SEND_METHOD.as_bytes(),permit.arguments())?;let size=bytes.expose_to_transport().len().checked_add(64).ok_or(CodecError::TooLarge)?;let budget=self.connection.reserve_native_rpc(size)?;permit.arm(id,deadline).map_err(|_|CodecError::InvalidField)?;self.next_id=id.checked_add(1);let request=ImSendRpcRequest::original(permit,id,budget)?;self.pending.insert(id,PendingRpc{kind:PendingKind::ImSend,selected_session_id:None,scheduler:None,call:None,im:None,received:None,user_read:None,send:Some(request)});Ok((id,bytes))}
    pub(in super::super) fn pending_im_send(&self,id:i32)->Option<Arc<ImSendRpcRequest>>{self.pending.get(&id).and_then(|p|p.send.clone())}
    pub(in super::super) fn take_im_send_replies(&mut self)->Vec<OwnedImSendReply>{std::mem::take(&mut self.send_replies)}
    pub(in super::super) fn retire_im_send(&mut self,id:i32){if self.pending.get(&id).is_some_and(|p|matches!(p.kind,PendingKind::ImSend)){self.pending.remove(&id);}}
    pub(super) fn captured_im_send_reply(&mut self,request:Arc<ImSendRpcRequest>,owner:&AttemptOwner,scope:&RpcConnectionScope,code:u32,bytes:&[u8])->Result<(),CodecError>{if self.phase()!=ArcPhase::Authenticated||!request.matches(owner,scope){self.close();return Err(CodecError::InvalidField);}let reply=match OwnedImSendReply::original(request,code,bytes){Ok(r)=>r,Err(e)=>{self.close();return Err(e);}};if self.im_reply_count()>=MAX_MAP_ENTRIES||self.im_reply_bytes().checked_add(reply.retained_bytes()).is_none_or(|n|n>super::super::rpc_stream::MAX_STREAM_BYTES){self.close();return Err(CodecError::TooLarge);}self.send_replies.push(reply);Ok(())}
}
